                'Дизајнерски тим Afarer-а провео је 3 недеље у марту 2023. проучавајући захтеве које је Simone поставила. Резултат: јога SUP даска „Serenity“ — ширина 34" (наспрам стандардних 32"), дужина 11\'6", са језгром од 7 слојева drop-stitch материјала за крутост и стабилност. Палуба је имала подлогу од EVA материјала са затвореним ћелијама дебљине 6 mm, са текстуром у дијамантском шаблону (измерен коефицијент трења: 0.85 на сувом, 0.72 на мокром), која покрива 85% површине палубе. Afarer је на нос даске додао санскртски симбол „Om“ у сребрној рефлективној техники топлог преноса, а око централне ручице за ношење шаблон лотоса. Даске су испоручене у 4 боје (корална, тиркизна, наранџаста заласка сунца, боја лагуне) које одговарају 4 палете боја Azure одмаралишта. Свака даска је имала 8 нерђајућих челичних D-прстенова — 4 за систем еластичне уже за причвршћивање јога струњача и 4 за опционална сидрене ужади за стационарну праксу у струји.',
