                'Током 5 дана у јулу 2025. Afarer-ов главни тренер спасавања спровео је сертификацију на плажи за 18 официра NBFD-а за безбедност на води. Курс је прилагођен условима западне обале: зарон кроз прибрежне таласе на SUP дасци, извлачење унесрећеног са стартом са плаже (превлачење унесрећеног на даску у таласима који се ломе) и координација сценарија уз подршку хеликоптера NBFD-а Bell 412. Rodriguez је захтевала да свих 18 официра положи завршни сценарио: проналажење симулираног унесрећеног (лутка од 80 kg) на 150 m од The Wedge у таласима од 2-3 ft, извођење имобилизације кичме у води и повратак на плажу — све у року од 8 минута. Стопа положених: 100%, са медијаном времена завршетка од 6 минута и 12 секунди.',
